function json(data, init={}) {
  const headers = new Headers(init.headers || {});
  headers.set('Content-Type','application/json; charset=utf-8');
  headers.set('Cache-Control','no-store');
  return new Response(JSON.stringify(data), {...init, headers});
}

function cleanText(v, max=80) {
  return String(v ?? '').trim().slice(0,max);
}

function slugify(value) {
  return cleanText(value,80)
    .normalize('NFD').replace(/[\u0300-\u036f]/g,'')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g,'-')
    .replace(/^-+|-+$/g,'')
    .slice(0,40) || 'pokemon';
}

function validPrice(v) {
  const n = Number(v);
  return Number.isFinite(n) && n > 0 && n <= 999;
}

function normalizeSignature(v) {
  return String(v || '')
    .trim()
    .toLowerCase()
    .replace(/\s+/g,'')
    .replace(/[–—_]/g,'-');
}

function normalizeIdentityText(v) {
  return cleanText(v,120)
    .normalize('NFD').replace(/[\u0300-\u036f]/g,'')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g,'')
    .trim();
}

function normalizeCaptureAt(v) {
  const raw = cleanText(v,40).replace(/\s+/g,' ');
  const m = raw.match(/(\d{2})\/(\d{2})\/(\d{4})\s+(\d{2}):(\d{2})/);
  if(!m) return '';
  return `${m[1]}/${m[2]}/${m[3]} ${m[4]}:${m[5]}`;
}

function speciesFromName(v) {
  return cleanText(v,80)
    .replace(/\s+#\d+\s*$/,'')
    .trim();
}

function makeLegacyKey({species,captureAt,quality,ivTotal}={}) {
  const sp = normalizeIdentityText(species);
  const cap = normalizeCaptureAt(captureAt);
  const q = Number(quality);
  const iv = Number(ivTotal);
  if(!sp || !cap || !Number.isFinite(q) || !Number.isFinite(iv)) return '';
  return `${sp}|${cap}|${q.toFixed(2)}|${Math.round(iv)}`;
}

function makeStatsKey({species,technical}={}) {
  const sp = normalizeIdentityText(species);
  const t = technical || {};
  const keys = ['hpIv','atkIv','defIv','spatkIv','spdefIv','speedIv'];
  const vals = keys.map(k=>Number(t[k]));
  if(!sp || !vals.every(v=>Number.isFinite(v) && v>=0 && v<=31)) return '';
  const q = Number(t.quality);
  const iv = Number(t.ivTotal);
  if(!Number.isFinite(q) || !Number.isFinite(iv)) return '';
  return `${sp}|${q.toFixed(2)}|${Math.round(iv)}|${vals.join('-')}`;
}

function normalizeIdentity(item={}, fallback={}) {
  const base = fallback.identity || {};
  const incoming = item.identity || {};
  const signature = normalizeSignature(incoming.signature || item.signature || base.signature || '');
  const captureAt = normalizeCaptureAt(incoming.captureAt || base.captureAt || '');
  const species = item.species || fallback.species || speciesFromName(item.name || fallback.name || '');
  const technical = {...(fallback.technical || {}), ...(item.technical || {})};
  const legacyKey = incoming.legacyKey || base.legacyKey || makeLegacyKey({
    species, captureAt, quality:technical.quality, ivTotal:technical.ivTotal
  });
  const statsKey = incoming.statsKey || base.statsKey || makeStatsKey({species,technical});
  return {
    signature: signature || null,
    captureAt: captureAt || null,
    legacyKey: legacyKey || null,
    statsKey: statsKey || null
  };
}

function validPriceForRarity(price, rarity) {
  const n = Number(price);
  if(!validPrice(n)) return false;
  const r = String(rarity || '').toUpperCase();
  if(r === 'ÉPICO') return n >= 7 && n <= 12;
  if(r === 'RARO') return n >= 4 && n <= 7;
  return true;
}

function normalizeCatalogItem(item, fallback={}) {
  const merged = {...fallback, ...item};
  const rarity = String(merged.rarity || fallback.rarity || 'ÉPICO').toUpperCase();
  merged.rarity = rarity;
  merged.species = cleanText(merged.species || speciesFromName(merged.name),80);
  merged.technical = {...(fallback.technical || {}), ...(item.technical || {})};
  merged.identity = normalizeIdentity(merged, fallback);
  merged.signature = merged.identity.signature;
  if(rarity === 'ÉPICO' && (!Number.isFinite(Number(merged.price)) || Number(merged.price) < 7 || Number(merged.price) > 12)){
    merged.price = Number(fallback.price || 7);
  }
  if(rarity === 'RARO' && (!Number.isFinite(Number(merged.price)) || Number(merged.price) < 4 || Number(merged.price) > 7)){
    merged.price = Number(fallback.price || 4);
  }
  return merged;
}

function findDuplicate(catalog, candidate, excludeId='') {
  const signature = normalizeSignature(candidate?.identity?.signature || candidate?.signature || '');
  const legacyKey = candidate?.identity?.legacyKey || '';
  const statsKey = candidate?.identity?.statsKey || '';

  for(const item of Object.values(catalog || {})) {
    if(!item || item.id === excludeId) continue;
    const identity = normalizeIdentity(item, item);

    if(signature && identity.signature && signature === identity.signature) {
      return {item, method:'signature'};
    }
    if(legacyKey && identity.legacyKey && legacyKey === identity.legacyKey) {
      return {item, method:'captura'};
    }
    if(statsKey && identity.statsKey && statsKey === identity.statsKey) {
      return {item, method:'ivs'};
    }
  }
  return null;
}


function normalizedDisplayName(item){
  return cleanText(item?.name || '',80)
    .normalize('NFD').replace(/[\u0300-\u036f]/g,'')
    .toLowerCase()
    .replace(/\s+/g,' ')
    .trim();
}

function integrityScore(item){
  let score = 0;
  const identity = normalizeIdentity(item,item);
  const t = item?.technical || {};
  if(item?.builtin === true) score += 100;
  if(identity.signature) score += 40;
  if(identity.legacyKey) score += 25;
  if(identity.statsKey) score += 30;
  if(Number.isFinite(Number(t.quality))) score += 8;
  if(Number.isFinite(Number(t.ivTotal))) score += 8;
  for(const k of ['hpIv','atkIv','defIv','spatkIv','spdefIv','speedIv']){
    if(Number.isFinite(Number(t[k]))) score += 2;
  }
  const q = Number(t.quality);
  const rarity = String(item?.rarity || '').toUpperCase();
  if(rarity === 'ÉPICO' && q >= 1.40 && q <= 1.54) score += 10;
  if(rarity === 'RARO' && q >= 1.25 && q <= 1.39) score += 10;
  return score;
}

function sameReviewedIdentity(a,b){
  const ia = normalizeIdentity(a,a);
  const ib = normalizeIdentity(b,b);

  if(ia.signature && ib.signature && ia.signature === ib.signature) return 'signature';
  if(ia.legacyKey && ib.legacyKey && ia.legacyKey === ib.legacyKey) return 'captura';
  if(ia.statsKey && ib.statsKey && ia.statsKey === ib.statsKey) return 'ivs';

  const sameName = normalizedDisplayName(a) && normalizedDisplayName(a) === normalizedDisplayName(b);
  if(sameName) return 'nome';

  return '';
}

function nextPokemonDisplayName(catalog,species){
  const sp = cleanText(species,80);
  let max = 0;
  for(const item of Object.values(catalog || {})){
    if(normalizeIdentityText(item?.species || speciesFromName(item?.name)) !== normalizeIdentityText(sp)) continue;
    const m = String(item?.name || '').match(/#\s*(\d+)\s*$/);
    if(m) max = Math.max(max, Number(m[1]) || 0);
  }
  return `${sp} #${String(max + 1).padStart(2,'0')}`;
}

function sanitizeSavedCatalog(baseCatalog,savedCatalog){
  const merged = structuredClone(baseCatalog || {});

  // Itens atuais de DEFAULTS são a fonte oficial.
  // Do KV antigo, só preservamos estado mutável de IDs que ainda existem.
  for(const [id,raw] of Object.entries(savedCatalog || {})){
    if(merged[id]){
      const current = merged[id];
      if(typeof raw?.sold === 'boolean') current.sold = raw.sold;
      if(validPriceForRarity(raw?.price,current.rarity)) current.price = Number(raw.price);
    }
  }

  // Itens extras criados pelo Admin continuam válidos,
  // mas itens builtin antigos que saíram da versão atual são descartados.
  for(const [id,raw] of Object.entries(savedCatalog || {})){
    if(merged[id]) continue;

    const candidate = normalizeCatalogItem(raw,{});
    candidate.id = id;

    if(candidate.builtin !== false){
      continue; // catálogo builtin obsoleto de versões antigas
    }

    let duplicate = null;
    for(const item of Object.values(merged)){
      const method = sameReviewedIdentity(item,candidate);
      if(method){
        duplicate = {item,method};
        break;
      }
    }

    if(duplicate){
      // O catálogo revisado/current DEFAULTS sempre vence uma cópia antiga.
      continue;
    }

    // Caso o item seja legítimo mas o nome não siga numeração,
    // normalizamos para um nome único da espécie.
    const species = candidate.species || speciesFromName(candidate.name);
    candidate.name = nextPokemonDisplayName(merged,species);
    merged[id] = candidate;
  }

  return merged;
}

async function readCatalog(env) {
  const base = structuredClone(DEFAULTS);
  if(!env.STORE) return base;

  try {
    const saved = await env.STORE.get('_catalog.json', 'json');
    if(!saved) return base;
    return sanitizeSavedCatalog(base,saved);
  } catch {
    return base;
  }
}

async function saveCatalog(env, catalog) {
  if(!env.STORE) throw new Error('KV não conectado ao Worker.');
  await env.STORE.put('_catalog.json', JSON.stringify(catalog));
}

function base64url(bytes) {
  let binary = '';
  const arr = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes);
  for(const b of arr) binary += String.fromCharCode(b);
  return btoa(binary).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');
}

function textBytes(value) {
  return new TextEncoder().encode(String(value));
}

async function hmacHex(secret, value) {
  const key = await crypto.subtle.importKey(
    'raw',
    textBytes(secret),
    {name:'HMAC', hash:'SHA-256'},
    false,
    ['sign']
  );
  const sig = await crypto.subtle.sign('HMAC', key, textBytes(value));
  return base64url(sig);
}

function getCookie(request, name) {
  const raw = request.headers.get('Cookie') || '';
  for(const part of raw.split(';')) {
    const [k, ...rest] = part.trim().split('=');
    if(k === name) return rest.join('=');
  }
  return '';
}

async function createSession(env) {
  const exp = Math.floor(Date.now()/1000) + 60*60*12;
  const nonce = crypto.randomUUID();
  const payload = `${exp}.${nonce}`;
  const sig = await hmacHex(env.SESSION_SECRET, payload);
  return `${payload}.${sig}`;
}

async function validSession(request, env) {
  if(!env.SESSION_SECRET) return false;
  const token = getCookie(request, 'pp_admin');
  if(!token) return false;

  const parts = token.split('.');
  if(parts.length !== 3) return false;
  const [expRaw, nonce, sig] = parts;
  const exp = Number(expRaw);
  if(!Number.isFinite(exp) || exp < Math.floor(Date.now()/1000)) return false;

  const expected = await hmacHex(env.SESSION_SECRET, `${expRaw}.${nonce}`);
  if(expected.length !== sig.length) return false;

  let diff = 0;
  for(let i=0;i<expected.length;i++) diff |= expected.charCodeAt(i) ^ sig.charCodeAt(i);
  return diff === 0;
}

async function requireAdmin(request, env) {
  return await validSession(request, env);
}

async function serveImage(env, id) {
  if(!/^[a-z0-9-]{3,120}$/i.test(id)) {
    return new Response('Imagem inválida',{status:400});
  }
  if(!env.STORE) return new Response('KV não conectado ao Worker.',{status:503});

  const entry = await env.STORE.getWithMetadata(`images/${id}`, 'arrayBuffer');
  if(!entry || !entry.value) return new Response('Imagem não encontrada',{status:404});

  const contentType = entry.metadata?.contentType || 'application/octet-stream';
  return new Response(entry.value, {
    headers:{
      'Content-Type':contentType,
      'Cache-Control':'public, max-age=3600'
    }
  });
}

async function adminCatalog(request, env) {
  if(!(await requireAdmin(request, env))) {
    return new Response('Acesso administrativo não autorizado.',{status:403});
  }

  if(request.method === 'GET') return json(await readCatalog(env));
  if(request.method !== 'POST') return new Response('Method not allowed',{status:405});

  const type = request.headers.get('content-type') || '';

  if(type.includes('multipart/form-data')) {
    const form = await request.formData();
    const action = cleanText(form.get('action'),20);

    if(action !== 'create') return new Response('Ação inválida.',{status:400});

    const requestedName = cleanText(form.get('name'),80);
    const species = cleanText(form.get('species') || speciesFromName(requestedName),80);
    const rarity = cleanText(form.get('rarity') || 'ÉPICO',30).toUpperCase();
    const price = Number(form.get('price'));
    const signature = normalizeSignature(form.get('signature'));
    const captureAt = normalizeCaptureAt(form.get('captureAt'));
    const file = form.get('image');

    if(requestedName.length < 2) return new Response('Informe o nome do Pokémon.',{status:400});
    if(species.length < 2) return new Response('Não consegui identificar a espécie.',{status:400});
    if(!validPriceForRarity(price, rarity)) {
      if(rarity === 'ÉPICO') return new Response('Pokémon épico deve custar entre R$ 7 e R$ 12.',{status:400});
      if(rarity === 'RARO') return new Response('Pokémon raro deve custar entre R$ 4 e R$ 7.',{status:400});
      return new Response('Preço inválido.',{status:400});
    }
    if(!(file instanceof File)) return new Response('Selecione o print.',{status:400});

    const allowed = new Set(['image/png','image/jpeg','image/webp']);
    if(!allowed.has(file.type)) return new Response('Use PNG, JPG/JPEG ou WEBP.',{status:400});
    if(file.size <= 0 || file.size > 8*1024*1024) {
      return new Response('A imagem deve ter até 8 MB.',{status:400});
    }

    const technical = {
      quality: form.get('quality') ? Number(form.get('quality')) : null,
      ivTotal: form.get('ivTotal') ? Number(form.get('ivTotal')) : null,
      hpIv: form.get('hpIv') ? Number(form.get('hpIv')) : null,
      atkIv: form.get('atkIv') ? Number(form.get('atkIv')) : null,
      defIv: form.get('defIv') ? Number(form.get('defIv')) : null,
      spatkIv: form.get('spatkIv') ? Number(form.get('spatkIv')) : null,
      spdefIv: form.get('spdefIv') ? Number(form.get('spdefIv')) : null,
      speedIv: form.get('speedIv') ? Number(form.get('speedIv')) : null,
      nature: cleanText(form.get('nature'),40) || null,
      gender: cleanText(form.get('gender'),20) || null,
      autoScore: form.get('autoScore') ? Number(form.get('autoScore')) : null
    };

    if(rarity === 'ÉPICO' && Number.isFinite(technical.quality) && (technical.quality < 1.40 || technical.quality > 1.54)){
      return new Response('Qualidade incompatível com ÉPICO. O Pokepixel usa a faixa x1,40–x1,54.',{status:400});
    }
    if(rarity === 'RARO' && Number.isFinite(technical.quality) && (technical.quality < 1.25 || technical.quality > 1.39)){
      return new Response('Qualidade incompatível com RARO. O Pokepixel usa a faixa x1,25–x1,39.',{status:400});
    }

    const ivKeys = ['hpIv','atkIv','defIv','spatkIv','spdefIv','speedIv'];
    const ivValues = ivKeys.map(k=>technical[k]);
    const needsAccurateStats = rarity === 'ÉPICO' || rarity === 'RARO';
    if(needsAccurateStats){
      if(!Number.isFinite(technical.quality) || !Number.isFinite(technical.ivTotal) || !ivValues.every(Number.isFinite)){
        return new Response('Épicos e Raros precisam de Qualidade, IV Total e os 6 IVs antes de publicar.',{status:400});
      }
      const ivSum = ivValues.reduce((a,b)=>a+b,0);
      if(ivSum !== technical.ivTotal){
        return new Response(`IVs divergentes: os 6 IVs somam ${ivSum}, mas o IV Total é ${technical.ivTotal}. Corrija antes de publicar.`,{status:400});
      }
    }

    const identity = {
      signature: signature || null,
      captureAt: captureAt || null,
      legacyKey: makeLegacyKey({species,captureAt,quality:technical.quality,ivTotal:technical.ivTotal}) || null,
      statsKey: makeStatsKey({species,technical}) || null
    };

    if(!identity.signature && !identity.legacyKey && !identity.statsKey) {
      return new Response(
        'Não há dados suficientes para verificar duplicidade. Informe a Assinatura ou mantenha espécie + data/hora de captura + IV Total + qualidade.',
        {status:400}
      );
    }

    const catalog = await readCatalog(env);
    const duplicate = findDuplicate(catalog,{species,technical,identity});
    if(duplicate){
      const methodLabel = duplicate.method === 'signature'
        ? 'assinatura/código único'
        : duplicate.method === 'captura'
          ? 'dados de captura'
          : 'IVs';
      return new Response(
        `Este Pokémon já está cadastrado como ${duplicate.item.name}. Duplicidade confirmada por ${methodLabel}.`,
        {status:409}
      );
    }

    const displayName = nextPokemonDisplayName(catalog,species);
    const id = `${slugify(displayName)}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,7)}`;
    const imageKey = `images/${id}`;

    if(!env.STORE) return new Response('KV não conectado ao Worker.',{status:503});

    await env.STORE.put(imageKey, await file.arrayBuffer(), {
      metadata:{
        contentType:file.type,
        filename:file.name,
        uploadedAt:new Date().toISOString()
      }
    });

    const nextOrder = Math.max(0,...Object.values(catalog).map(x=>Number(x.addedOrder)||0)) + 1;

    catalog[id] = {
      id, name:displayName, species, price, sold:false, rarity,
      signature: identity.signature,
      identity,
      imageUrl:`/api/image/${encodeURIComponent(id)}`,
      imageKey, builtin:false, createdAt:new Date().toISOString(),
      addedOrder:nextOrder,
      technical
    };

    await saveCatalog(env, catalog);
    return json({ok:true,item:catalog[id]});
  }

  const body = await request.json();
  const catalog = await readCatalog(env);
  const id = cleanText(body.id,120);

  if(body.action === 'delete') {
    const item = catalog[id];
    if(!item) return new Response('Pokémon não encontrado.',{status:404});
    if(item.builtin) {
      return new Response('Os Pokémon originais ficam protegidos contra exclusão.',{status:400});
    }
    if(item.imageKey) await env.STORE.delete(item.imageKey);
    delete catalog[id];
    await saveCatalog(env,catalog);
    return json({ok:true,deleted:id});
  }

  if(!catalog[id]) return new Response('Pokémon não encontrado.',{status:404});
  const item = catalog[id];

  if(typeof body.sold === 'boolean') item.sold = body.sold;
  if(body.price !== undefined) {
    if(!validPriceForRarity(body.price, item.rarity)) {
      return new Response(String(item.rarity || '').toUpperCase() === 'ÉPICO' ? 'Pokémon épico deve custar entre R$ 7 e R$ 12.' : 'Preço inválido.',{status:400});
    }
    item.price = Number(body.price);
  }
  if(body.name !== undefined) {
    const name = cleanText(body.name,80);
    if(name.length < 2) return new Response('Nome inválido.',{status:400});
    item.name = name;
  }

  catalog[id] = item;
  await saveCatalog(env,catalog);
  return json({ok:true,item});
}



async function duplicateCheck(request, env) {
  if(!(await requireAdmin(request, env))) {
    return new Response('Acesso administrativo não autorizado.',{status:403});
  }
  if(request.method !== 'POST') return new Response('Method not allowed',{status:405});

  const body = await request.json().catch(()=>({}));
  const species = cleanText(body.species || speciesFromName(body.name),80);
  const technical = body.technical || {};
  const identity = {
    signature: normalizeSignature(body.signature),
    captureAt: normalizeCaptureAt(body.captureAt),
    legacyKey: makeLegacyKey({
      species,
      captureAt:body.captureAt,
      quality:technical.quality,
      ivTotal:technical.ivTotal
    }) || null,
    statsKey: makeStatsKey({species,technical}) || null
  };

  const catalog = await readCatalog(env);
  const duplicate = findDuplicate(catalog,{species,technical,identity});

  if(duplicate){
    return json({
      duplicate:true,
      method:duplicate.method,
      item:{
        id:duplicate.item.id,
        name:duplicate.item.name,
        rarity:duplicate.item.rarity,
        sold:Boolean(duplicate.item.sold)
      }
    });
  }

  return json({
    duplicate:false,
    identityReady:Boolean(identity.signature || identity.legacyKey || identity.statsKey),
    methodsAvailable:{
      signature:Boolean(identity.signature),
      capture:Boolean(identity.legacyKey),
      ivs:Boolean(identity.statsKey)
    }
  });
}

async function loginAdmin(request, env) {
  if(request.method !== 'POST') return new Response('Method not allowed',{status:405});
  if(!env.ADMIN_PASSWORD || !env.SESSION_SECRET){
    return new Response('Segredos do admin ainda não configurados.',{status:503});
  }

  const body = await request.json().catch(()=>({}));
  const password = String(body.password || '');
  if(password !== env.ADMIN_PASSWORD){
    return new Response('Senha incorreta.',{status:401});
  }

  const token = await createSession(env);
  return json({ok:true},{
    headers:{
      'Set-Cookie':`pp_admin=${token}; Path=/admin; HttpOnly; Secure; SameSite=Strict; Max-Age=43200`
    }
  });
}

async function logoutAdmin() {
  return json({ok:true},{
    headers:{
      'Set-Cookie':'pp_admin=; Path=/admin; HttpOnly; Secure; SameSite=Strict; Max-Age=0'
    }
  });
}

async function sessionStatus(request, env) {
  return json({authenticated:await validSession(request, env)});
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);

    if(url.pathname === '/api/catalog' && request.method === 'GET') {
      return json(await readCatalog(env));
    }

    if(url.pathname.startsWith('/api/image/') && request.method === 'GET') {
      const id = decodeURIComponent(url.pathname.slice('/api/image/'.length));
      return serveImage(env, id);
    }

    if(url.pathname === '/admin/api/login') {
      return loginAdmin(request, env);
    }

    if(url.pathname === '/admin/api/logout') {
      return logoutAdmin();
    }

    if(url.pathname === '/admin/api/session') {
      return sessionStatus(request, env);
    }

    if(url.pathname === '/admin/api/duplicate-check') {
      return duplicateCheck(request, env);
    }

    if(url.pathname === '/admin/api/catalog') {
      return adminCatalog(request, env);
    }

    return env.ASSETS.fetch(request);
  }
};
